long long findTargetSumWays(vector<int>& a, int target) {
    int S = accumulate(a.begin(), a.end(), 0); if (abs(target) > S || (S + target) % 2) return 0; int t = (S + target) / 2;
    vector<long long> dp(t + 1, 0); dp[0] = 1; for (int x : a) for (int s = t; s >= x; s--) dp[s] += dp[s - x];
    return dp[t];
}
